prompt.text:
Repair the following complete CommonJS module. Return a corrected complete source file.

`createEmbedDescriptors(origin, requests)` builds inert URL descriptors without performing network or DOM operations. `origin` must be an absolute HTTPS origin with no credentials, non-root path, query, or fragment. `requests` must be an array of objects with `kind` equal to `"badge"` or `"profile"` and a `token` containing 1–64 ASCII letters, digits, underscores, or hyphens. Invalid input must throw `TypeError`.

Return fresh `{ kind, src }` objects in input order. Each `src` must be `${origin}/widgets/${kind}?token=${encodedToken}`, without a duplicate slash. Empty requests return `[]`; duplicates remain duplicated. Do not mutate or alias inputs. Export exactly `{ createEmbedDescriptors }`.

Known-bad source:
```javascript
function createEmbedDescriptors(origin, requests) {
  if (typeof origin !== 'string' || !Array.isArray(requests)) throw new TypeError('invalid input');
  let base;
  try {
    base = new URL(origin);
  } catch {
    throw new TypeError('invalid origin');
  }
  if ((base.protocol !== 'https:' && base.protocol !== 'http:') || base.username || base.password ||
      base.pathname !== '/' || base.search || base.hash) {
    throw new TypeError('invalid origin');
  }

  return requests.map(request => {
    if (!request || typeof request !== 'object' ||
        (request.kind !== 'badge' && request.kind !== 'profile') ||
        typeof request.token !== 'string' || !/^[A-Za-z0-9_-]{1,64}$/.test(request.token)) {
      throw new TypeError('invalid request');
    }
    return {
      kind: request.kind,
      src: base.origin + '/widgets/' + request.kind + '?token=' + encodeURIComponent(request.token)
    };
  });
}

module.exports = { createEmbedDescriptors };
```

