'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['createEmbedDescriptors']);
const { createEmbedDescriptors } = api;

assert.deepEqual(createEmbedDescriptors('https://example.com', []), []);
assert.deepEqual(createEmbedDescriptors('https://example.com/', []), []);

const requests = Object.freeze([
  Object.freeze({ kind: 'badge', token: 'Abc_123-x' }),
  Object.freeze({ kind: 'profile', token: 'token' }),
  Object.freeze({ kind: 'badge', token: 'Abc_123-x' })
]);
const result = createEmbedDescriptors('https://example.com/', requests);
assert.deepEqual(result, [
  { kind: 'badge', src: 'https://example.com/widgets/badge?token=Abc_123-x' },
  { kind: 'profile', src: 'https://example.com/widgets/profile?token=token' },
  { kind: 'badge', src: 'https://example.com/widgets/badge?token=Abc_123-x' }
]);
assert.notStrictEqual(result, requests);
assert.notStrictEqual(result[0], result[2]);
assert.equal(requests[0].token, 'Abc_123-x');

const token64 = 'A'.repeat(64);
assert.deepEqual(createEmbedDescriptors('https://example.com:8443', [{ kind: 'badge', token: token64 }]), [
  { kind: 'badge', src: 'https://example.com:8443/widgets/badge?token=' + token64 }
]);

for (const origin of [
  'http://example.com',
  'example.com',
  'https://user@example.com',
  'https://example.com/path',
  'https://example.com/?q=1',
  'https://example.com/#frag'
]) {
  assert.throws(() => createEmbedDescriptors(origin, []), TypeError);
}
assert.throws(() => createEmbedDescriptors('https://example.com', {}), TypeError);
for (const request of [
  null,
  {},
  { kind: 'other', token: 'abc' },
  { kind: 'badge', token: '' },
  { kind: 'badge', token: 'a'.repeat(65) },
  { kind: 'badge', token: 'bad token' },
  { kind: 'badge', token: 'é' },
  { kind: 'badge', token: 123 }
]) {
  assert.throws(() => createEmbedDescriptors('https://example.com', [request]), TypeError);
}

